        private static void OnPlayModeStateChanged(PlayModeStateChange state)
        {
            if (!s_Watching || !EditorSettings.enterPlayModeOptionsEnabled ||
                (EditorSettings.enterPlayModeOptions & EnterPlayModeOptions.DisableDomainReload) == 0)
                return;

            if (state == PlayModeStateChange.EnteredPlayMode
#if UNITY_7000_0_OR_NEWER
                || state == PlayModeStateChange.EnteredEditMode
#endif
                )
            {
                // Session cleanup cleared the overrides, but no compile changed the watched source.
                // Queue through the normal debounce after the new session has registered its targets.
                QueueJournaledReapplies();
            }
        }

        private static void QueueJournaledReapplies()
        {
            double now = EditorApplication.timeSinceStartup;
            foreach (var path in ComputeResumeReapplies(true, GetJournaledAppliedFiles()))
                s_Pending[path] = now;

