/// These statics describe the current Play session. Explicit lifecycle cleanup resets them
/// together with RuntimePipelineDriver's discovery latch, even when domain reload is disabled.
/// The lock and collection instances stay valid for the editor server across transitions.

#if UNITY_7000_0_OR_NEWER
        [OnEnteringPlayMode]
        [OnExitingPlayMode]
#else
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
#endif
        private static void ResetSessionState()
        {
            RuntimePipelineDriver.ResetMethodReloadDiscoveryLatch(ClearSessionState);
        }

        private static void ClearSessionState()
        {
            m_MethodOverrides.Clear();
            m_ReloadableMethods.Clear();
            m_LoadedMethodReloadTypes.Clear();
            Dispatcher = null;
            AllowedReloadRoots = null;
            OverridesChanged = null;
            lock (s_FirstReloadNotes)
            {
                s_FirstReloadNotes.Clear();
                s_FirstReloadNotesFlushed = false;
            }
        }
